import { expect, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
    // Arrange: a Globex vendor with an uploaded document, created as the other tenant
    const globex = await apiAs("otherTenant");
    const vendorRes = await globex.post("/api/vendors", {
      data: { name: uniqueName("Globex Vendor"), category: "services", contact_email: "ops@globexvendor.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = (await vendorRes.json()) as { id: string };

    const uploadRes = await globex.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.from("W-9 test document") },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const document = (await uploadRes.json()) as { id: string };

    // Act: request that document as a Northwind member
    const member = await apiAs("member");
    const response = await member.get(`/api/documents/${document.id}`);

    // Assert
    expect(response.status(), await response.text()).toBe(404);
    const body = (await response.json()) as { error: { code: string } };
    expect(body.error.code).toBe("document_not_found");
  });
});
